// Generated base metadata from minecraft-data Java 1.21.11 blocks.json. State rules below are explicit.
export const LIGHT_DATA_VERSION = 'Java 1.21.11 metadata with explicit state overrides'

export const LIGHT_FACE = Object.freeze({ POS_X: 1, NEG_X: 2, POS_Y: 4, NEG_Y: 8, POS_Z: 16, NEG_Z: 32, ALL: 63 })

const clamp15 = value => Math.max(0, Math.min(15, Number(value) || 0))

export function getMinecraftLightProperties(state = 'minecraft:air') {
  const text = typeof state === 'string' ? state : String(state?.Name || state?.name || '')
  const match = /^([^[]+)(?:\[([^\]]*)\])?$/.exec(text)
  const name = (match?.[1] || text).replace(/^minecraft:/, '')
  const base = BLOCKS[name]
  if (!base)
    return { known: false, name, opacity: 15, emission: 0, ao: 255, faceOcclusion: LIGHT_FACE.ALL, reason: `Unknown block: ${name}` }
  const properties = { ...base[3], ...(typeof state === 'object' ? state.Properties || state.properties || {} : {}) }
  for (const part of (match?.[2] || '').split(',')) {
    const [key, value] = part.split('=')
    if (key && value !== undefined)
      properties[key] = value
  }
  const yes = key => String(properties[key]) === 'true'
  let opacity = base[0]
  let emission = base[1]
  let fullOpaque = !!base[2]
  if (name.endsWith('_slab')) {
    fullOpaque = properties.type === 'double'
    opacity = fullOpaque ? 15 : 0
  }
  if (name.endsWith('_stairs') || name.endsWith('_wall') || name.endsWith('_fence') || name.endsWith('_trapdoor') || name.endsWith('_door'))
    fullOpaque = false
  if (name === 'snow') {
    fullOpaque = Number(properties.layers) === 8
    opacity = fullOpaque ? 15 : 0
  }
  if (name === 'piston' || name === 'sticky_piston') {
    fullOpaque = !yes('extended')
    opacity = fullOpaque ? 15 : 0
  }
  if (name === 'piston_head' || name === 'moving_piston') {
    fullOpaque = false
    opacity = 0
  }
  if (name === 'tinted_glass') {
    opacity = 15
    fullOpaque = false
  }
  if (name === 'water' || name.endsWith('_leaves')) {
    opacity = 1
    fullOpaque = false
  }
  if (name === 'glass' || name.endsWith('_stained_glass') || name.endsWith('_glass_pane')) {
    opacity = 0
    fullOpaque = false
  }
  if (yes('waterlogged') && opacity < 15)
    opacity = Math.max(1, opacity)
  if (name === 'redstone_torch' || name === 'redstone_wall_torch')
    emission = yes('lit') ? 7 : 0
  else if (name === 'torch' || name === 'wall_torch')
    emission = properties.lit === 'false' ? 0 : 14
  else if (name === 'redstone_lamp')
    emission = yes('lit') ? 15 : 0
  else if (['furnace', 'blast_furnace', 'smoker'].includes(name))
    emission = yes('lit') ? 13 : 0
  else if (name === 'campfire' || name === 'soul_campfire')
    emission = yes('lit') && !yes('waterlogged') ? (name === 'campfire' ? 15 : 10) : 0
  else if (name.endsWith('candle_cake'))
    emission = yes('lit') ? 3 : 0
  else if (name === 'candle' || name.endsWith('_candle'))
    emission = yes('lit') && !yes('waterlogged') ? 3 * Math.max(1, Math.min(4, Number(properties.candles) || 1)) : 0
  else if (name === 'respawn_anchor')
    emission = [0, 3, 7, 11, 15][Math.max(0, Math.min(4, Number(properties.charges) || 0))]
  else if (name === 'light')
    emission = clamp15(properties.level)
  else if (name.endsWith('copper_bulb'))
    emission = yes('lit') ? (name.includes('oxidized') ? 4 : name.includes('weathered') ? 8 : name.includes('exposed') ? 12 : 15) : 0
  else if (name === 'cave_vines' || name === 'cave_vines_plant')
    emission = yes('berries') ? 14 : 0
  else if (name === 'sea_pickle')
    emission = yes('waterlogged') ? 3 * Math.max(1, Math.min(4, Number(properties.pickles) || 1)) + 3 : 0
  // Only complete boundary faces are represented; partial side-face unions remain
  // a documented approximation instead of guessing from collision boxes.
  let faceOcclusion = opacity === 15 ? LIGHT_FACE.ALL : 0
  if (name.endsWith('_slab') && properties.type !== 'double')
    faceOcclusion = properties.type === 'top' ? LIGHT_FACE.POS_Y : LIGHT_FACE.NEG_Y
  if (name.endsWith('_stairs'))
    faceOcclusion = properties.half === 'top' ? LIGHT_FACE.POS_Y : LIGHT_FACE.NEG_Y
  return { known: true, name, opacity: clamp15(opacity), emission: clamp15(emission), ao: fullOpaque && opacity === 15 ? 255 : 0, faceOcclusion }
}
